def split(field):
    return [item for item in field.split() if item]


def build():
    prompts = []
    for mood, rows in MUSIC.items():
        counts = {}
        for style, intensity, energy, study, emotions, situations, text in rows:
            counts[style] = counts.get(style, 0) + 1
            prompts.append(dict(id=f"music.{mood}.{style}.{counts[style]}", layer="music", text=text, style=style,
                                mood=mood, emotions=split(emotions), situations=split(situations),
                                intensity=intensity, energy=energy, studySafe=study))
    for bed, rows in AMBIENCE.items():
        for index, (style, setting, intensity, energy, study, situations, text) in enumerate(rows, 1):
            entry = dict(id=f"sfx.{bed}.{index}", layer="ambience", text=text, bed=bed, emotions=[],
                         situations=split(situations), intensity=intensity, energy=energy, studySafe=study)
            if style:
                entry["style"] = style
            if setting:
                entry["setting"] = setting
            prompts.append(entry)
    return {"version": VERSION, "prompts": prompts}


if __name__ == "__main__":
    out = Path(__file__).resolve().parents[2] / "NodusReader/Resources/Soundscapes/prompts.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    data = build()
    out.write_text(json.dumps(data, indent=1, ensure_ascii=False) + "\n")
    music = sum(1 for p in data["prompts"] if p["layer"] == "music")
    print(f"wrote {out} ({len(data['prompts'])} prompts: {music} music, {len(data['prompts']) - music} ambience)")
